#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parse, count } from './election.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
let election
try {
  election = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!e.isInputError) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
const { lines, winner } = count(election)
const rounds = lines.filter((l) => l.startsWith('round ')).length
let out = mode === 'rounds' ? lines.join('\n') + '\n' : `rounds ${rounds}\n`
out += winner === null ? 'no winner\n' : `winner ${winner}\n`
process.stdout.write(out)
EOF
cat > src/election.js <<'EOF'
const NAME = /^[A-Za-z0-9_-]+$/

function fail(msg) {
  const e = new Error(msg)
  e.isInputError = true
  throw e
}

export function parse(text) {
  const rows = text.split('\n')
  if (rows[rows.length - 1] === '') rows.pop()
  let candidates = null
  const ballots = []
  rows.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  })
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // per round: Map name -> votes
  const lines = []
  for (let k = 1; ; k++) {
    const votes = new Map([...continuing].map((c) => [c, 0]))
    let active = 0
    let total = 0
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const sorted = [...votes.keys()].sort((a, b) => votes.get(b) - votes.get(a) || cmp(a, b))
    lines.push(`round ${k}: ${sorted.map((c) => `${c}=${votes.get(c)}`).join(' ')} exhausted=${total - active}`)
    if (active === 0) return { lines, winner: null }
    const top = sorted.find((c) => votes.get(c) * 2 > active)
    if (top !== undefined) return { lines, winner: top }
    let set = [...continuing]
    for (;;) {
      if (set.length === 1) break
      const r = history.find((h) => new Set(set.map((c) => h.get(c))).size > 1)
      if (!r) break
      const min = Math.min(...set.map((c) => r.get(c)))
      set = set.filter((c) => r.get(c) === min)
    }
    const out = set.sort(cmp).pop()
    continuing.delete(out)
    lines.push(`eliminated ${out}`)
  }
}
EOF
