{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (m) => [...m.keys()].sort(cmp)

function scalarJson(n) {
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v) ?? 'null'
}

function emit(n, ind) {
  if (n.t === 'table') {
    if (n.m.size === 0) return '{}'
    const pad = '  '.repeat(ind + 1)
    const parts = sortedKeys(n.m).map((k) => `${pad}${JSON.stringify(k)}: ${emit(n.m.get(k), ind + 1)}`)
    return `{\n${parts.join(',\n')}\n${'  '.repeat(ind)}}`
  }
  if (n.t === 'array') {
    if (n.items.length === 0) return '[]'
    const pad = '  '.repeat(ind + 1)
    const parts = n.items.map((x) => `${pad}${emit(x, ind + 1)}`)
    return `[\n${parts.join(',\n')}\n${'  '.repeat(ind)}]`
  }
  return scalarJson(n)
}

export function toJson(root) {
  return emit(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n.m)) visit(n.m.get(k), path === null ? k : `${path}.${k}`)
    } else if (n.t === 'array') {
      n.items.forEach((x, i) => visit(x, `${path}[${i}]`))
    }
  }
  const visit = (n, path) => {
    lines.push(`${path} ${n.t}`)
    walk(n, path)
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
    this.line = 0
  }
}

const fail = (r) => {
  throw new ParseError(r)
}

const newTable = () => ({ t: 'table', m: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INT = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS}(?:[eE][+-]?${DIGITS})?|[eE][+-]?${DIGITS})$`)

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  // at end of line or at a comment start (after whitespace skipped)
  atEnd() {
    const c = this.c
    return c === undefined || c === '#' || c === ';'
  }

  string(unterminated = 'unterminated string') {
    const q = this.c
    this.i++
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail(unterminated)
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      const e = this.c
      if (e === undefined) fail('unterminated string')
      // take a full code point for the message
      const ch = String.fromCodePoint(this.s.codePointAt(this.i))
      this.i += ch.length
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail(`invalid escape \\${ch}`)
    }
  }

  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.string()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.c)) this.i++
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c !== '.') {
        this.i = save
        return parts
      }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value(prefix) {
    const c = this.c
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail(`invalid value ${w}`)
  }

  array(prefix) {
    this.i++
    const items = []
    let first = true
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      if (this.c === ',') fail('expected a value')
      items.push(this.value(prefix))
      first = false
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') this.i++
      else if (this.c !== ']') fail('unterminated array')
    }
  }

  inline(prefix) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const parts = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(prefix)
      assign(tbl, prefix, parts, v)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === '}') {
        this.i++
        return tbl
      }
      if (this.c !== ',') fail('unterminated inline table')
      this.i++
    }
  }
}

// Walk (creating) the tables for the given path parts; returns the table reached.
function walk(tbl, prefix, parts) {
  let cur = tbl
  let path = prefix
  for (const p of parts) {
    path = path === '' ? p : `${path}.${p}`
    let n = cur.m.get(p)
    if (n === undefined) {
      n = newTable()
      cur.m.set(p, n)
    } else if (n.t === 'array' && n.aot) {
      n = n.items[n.items.length - 1]
    } else if (n.t !== 'table') fail(`${path} is not a table`)
    cur = n
  }
  return cur
}

function assign(tbl, prefix, parts, value) {
  const t = walk(tbl, prefix, parts.slice(0, -1))
  const path = [prefix, ...parts].filter((x, i) => i > 0 || x !== '').join('.')
  const key = parts[parts.length - 1]
  if (t.m.has(key)) fail(`key ${path} is defined twice`)
  t.m.set(key, value)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      const c = L.c
