      if (c === '[') {
        const r = header(L, root)
        current = r.table
        curPath = r.path
      } else {
        const parts = L.dotted()
        L.ws()
        if (L.c !== '=') fail('expected key = value')
        L.i++
        L.ws()
        const v = L.value(curPath)
        L.ws()
        if (!L.atEnd()) fail('trailing text after a value')
        assign(current, curPath, parts, v)
      }
    } catch (e) {
      if (e instanceof ParseError) e.line = n + 1
      throw e
    }
  }
  return root
}

function header(L, root) {
  const dbl = L.s[L.i + 1] === '['
  L.i += dbl ? 2 : 1
  L.ws()
  const parts = L.dotted()
  L.ws()
  if (L.c === undefined || L.c === '#' || L.c === ';') fail('unterminated table header')
  if (L.c !== ']') fail('unterminated table header')
  L.i++
  if (dbl) {
    if (L.c !== ']') fail('unterminated table header')
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  const path = parts.join('.')
  const parent = walk(root, '', parts.slice(0, -1))
  const key = parts[parts.length - 1]
  const n = parent.m.get(key)
  if (dbl) {
    const fresh = newTable()
    if (n === undefined) parent.m.set(key, { t: 'array', items: [fresh], aot: true })
    else if (n.t === 'array' && n.aot) n.items.push(fresh)
    else fail(`${path} is not an array of tables`)
    return { table: fresh, path }
  }
  if (n === undefined) {
    const t = newTable()
    t.header = true
    parent.m.set(key, t)
    return { table: t, path }
  }
  if (n.t !== 'table') fail(`${path} is not a table`)
  if (n.header) fail(`table ${path} is defined twice`)
  n.header = true
  return { table: n, path }
}
