const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  const history = []
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.ranks.find((r) => continuing.has(r))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    history.push(votes)
    const round = { votes, exhausted: total - active, eliminated: null, winner: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of votes) {
      if (v * 2n > active) { round.winner = c; return { rounds, winner: c } }
    }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let tied = [...votes].filter(([, v]) => v === min).map(([c]) => c)
    while (tied.length > 1) {
      let narrowed = false
      for (const h of history) {
        const vs = tied.map((c) => h.get(c))
        let m = vs[0]
        for (const v of vs) if (v < m) m = v
        if (vs.some((v) => v !== m)) {
          tied = tied.filter((c) => h.get(c) === m)
          narrowed = true
          break
        }
      }
      if (!narrowed) break
    }
    tied.sort(cmp)
    const out = tied[tied.length - 1]
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
