export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  let declared = false
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(`error: line ${n}: ${m}`) }
    if (t[0] === 'candidates') {
      if (declared || ballots.length) fail('candidates must be declared once, before any ballot')
      if (t.length < 2) fail('expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`invalid candidate name ${name}`)
        if (seen.has(name)) fail(`candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
      declared = true
    } else if (t[0] === 'ballot') {
      if (!declared) fail('candidates must be declared once, before any ballot')
      if (t.length < 3) fail('expected ballot <count> <candidate>...')
      if (!COUNT.test(t[1])) fail('count must be a positive integer')
      const set = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`unknown candidate ${name}`)
        if (set.has(name)) fail(`candidate ${name} is repeated`)
        set.add(name)
      }
      ballots.push({ count: BigInt(t[1]), ranks: t.slice(2) })
    } else {
      fail(`unknown directive ${t[0]}`)
    }
  }
  if (!declared) throw new ParseError('error: no candidates')
  return { candidates, ballots }
}
