{"file_path":"src/parse.js","content":"import { parseAddr } from './addr.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=+\-*/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

class Fail extends Error {}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const isCall = (i) => toks[i].k === 'word' && i + 1 < toks.length && toks[i + 1].k === 'op' && toks[i + 1].v === '('

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (peekOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return atom()
  }
  function atom() {
    if (p >= toks.length) throw new Fail()
    const tk = toks[p]
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op') {
      if (tk.v === '(') {
        p++
        const e = comparison()
        if (!peekOp(')')) throw new Fail()
        p++
        return { t: 'paren', e }
      }
      throw new Fail()
    }
    if (isCall(p)) {
      const name = tk.v.toUpperCase()
      p += 2
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(comparison())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          throw new Fail()
        }
      }
      return { t: 'call', name, args }
    }
    p++
    const up = tk.v.toUpperCase()
    if (up === 'TRUE' || up === 'FALSE') return { t: 'bool', v: up === 'TRUE' }
    const ref = { t: 'ref', text: tk.v, addr: parseAddr(tk.v) }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word' || isCall(p)) throw new Fail()
      const t2 = toks[p++]
      const u2 = t2.v.toUpperCase()
      if (u2 === 'TRUE' || u2 === 'FALSE') throw new Fail()
      return { t: 'range', a: ref.addr, b: parseAddr(t2.v) }
    }
    return ref
  }
  function check(n, isArg) {
    switch (n.t) {
      case 'range': if (!isArg) throw new Fail(); break
      case 'bin': check(n.l, false); check(n.r, false); break
      case 'un': case 'paren': check(n.e, false); break
      case 'call': for (const a of n.args) check(a, true); break
    }
  }
  try {
    const ast = comparison()
    if (p !== toks.length) return null
    check(ast, false)
    return ast
  } catch (e) {
    if (e instanceof Fail) return null
    throw e
  }
}

export function collectRefs(n, map) {
  switch (n.t) {
    case 'ref': if (n.addr) map.set(n.addr.key, n.addr); break
    case 'range':
      if (n.a && n.b) {
        const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
        const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
        for (let c = c1; c <= c2; c++) {
          for (let r = r1; r <= r2; r++) {
            const a = cellAt(c, r)
            map.set(a.key, a)
          }
        }
      }
      break
    case 'bin': collectRefs(n.l, map); collectRefs(n.r, map); break
    case 'un': case 'paren': collectRefs(n.e, map); break
    case 'call': for (const a of n.args) collectRefs(a, map); break
  }
}

import { colName } from './addr.js'
export function cellAt(col, row) {
  return { col, row, key: colName(col) + row }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula, cellAt } from './parse.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })
const ZERO = num(0)

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function rank(v) { return v.t === 'n' ? 0 : v.t === 's' ? 1 : 2 }

function cmpText(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.t === 's') return cmpText(a.v, b.v)
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}

function finite(v) {
  return Number.isFinite(v) ? num(v) : err('#DIV/0!')
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.visiting = new Set()
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    if (this.visiting.has(key)) return err('#CYCLE!')
    this.visiting.add(key)
    const v = this.compute(cell.content)
    this.visiting.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(content) {
    if (content[0] === '=') {
      const ast = parseFormula(content.slice(1))
      if (!ast) return err('#ERR!')
      return this.ev(ast)
    }
    if (content === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  expand(n) {
    if (!n.a || !n.b) return [err('#REF!')]
    const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
    const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
    const out = []
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(this.get(cellAt(c, r).key))
    return out
  }

  scalar(n) {
    if (n.t === 'range') {
      const vs = this.expand(n)
      const e = vs.find((v) => v.t === 'e')
      if (e) return e
      return vs.length === 1 ? vs[0] : err('#VALUE!')
    }
    return this.ev(n)
  }

  ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return n.addr ? this.get(n.addr.key) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l), r = this.ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      case '^': return finite(Math.pow(a.v, b.v))
    }
    return err('#ERR!')
  }

  call(n) {
    const name = n.name
    const k = n.args.length
    const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (multi.includes(name)) {
      if (k < 1) return err('#ERR!')
      const vals = []
      for (const a of n.args) {
        if (a.t === 'range') vals.push(...this.expand(a))
        else vals.push(this.ev(a))
      }
      const e = vals.find((v) => v.t === 'e')
      if (e) return e
      if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
      const nums = []
      for (const v of vals) {
        const x = toNum(v)
        if (x.t === 'e') return x
        nums.push(x.v)
      }
      if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
      if (name === 'AVG') return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
      if (name === 'MIN') return num(Math.min(...nums))
      return num(Math.max(...nums))
    }
    if (name === 'ABS') {
