{"file_path":"src/addr.js","content":"export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}

export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const k = i - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

export function parseAddr(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = colIndex(letters)
  return { col, row, key: letters + row }
}
