const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

export function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const hp = a.slice(at + 1)
  const from = hp.lastIndexOf(']') + 1
  const colon = hp.indexOf(':', from)
  if (colon < 0) return { userinfo, host: hp, port: undefined }
  return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
}

export function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../')) { inp = inp.slice(3); out.pop() }
    else if (inp === '/..') { inp = '/'; out.pop() }
    else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
const pct = (s) =>
  s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })

export function resolve(base, ref) {
  const r = parse(ref)
  const b = parse(base)
  const t = {}
  if (r.scheme !== undefined) {
    Object.assign(t, r)
    t.path = removeDots(r.path)
  } else if (r.authority !== undefined) {
    Object.assign(t, r, { scheme: b.scheme })
    t.path = removeDots(r.path)
  } else {
    t.scheme = b.scheme
    t.authority = b.authority
    t.fragment = r.fragment
    if (r.path === '') {
      t.path = b.path
      t.query = r.query !== undefined ? r.query : b.query
    } else {
      t.query = r.query
      if (r.path.startsWith('/')) t.path = removeDots(r.path)
      else {
        let merged
        if (b.authority !== undefined && b.path === '') merged = '/' + r.path
        else {
          const i = b.path.lastIndexOf('/')
          merged = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
        }
        t.path = removeDots(merged)
      }
    }
  }
  return t
}

/** Returns {error: component} or {text}. */
export function normalize(c) {
  const a = c.authority !== undefined ? splitAuthority(c.authority) : undefined
  if (truncated(c.path)) return { error: 'path' }
  if (a && a.userinfo !== undefined && truncated(a.userinfo)) return { error: 'userinfo' }
  if (a && truncated(a.host)) return { error: 'host' }
  if (c.query !== undefined && truncated(c.query)) return { error: 'query' }
  if (c.fragment !== undefined && truncated(c.fragment)) return { error: 'fragment' }
  const scheme = c.scheme !== undefined ? lower(c.scheme) : undefined
  let out = scheme !== undefined ? scheme + ':' : ''
  let path = removeDots(pct(c.path))
  if (a) {
    let auth = ''
    if (a.userinfo !== undefined) auth += pct(a.userinfo) + '@'
    auth += lower(pct(a.host))
