#!/usr/bin/env node
/**
 * `node src/cli.js normalize|resolve` reads one record per stdin line and
 * prints one normalized URI per line.
 */
import { readFileSync } from 'node:fs'
import { parse, resolve, normalize } from './uri.js'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const out = []
lines.forEach((line, idx) => {
  const n = idx + 1
  let comps
  if (mode === 'normalize') comps = parse(line)
  else {
    const sp = line.indexOf(' ')
    if (sp < 0) fail(`line ${n}: expected a base and a reference`)
    const base = line.slice(0, sp)
    if (parse(base).scheme === undefined) fail(`line ${n}: the base has no scheme`)
    comps = resolve(base, line.slice(sp + 1))
  }
  const r = normalize(comps)
  if (r.error) fail(`line ${n}: the ${r.error} has a truncated percent-encoding`)
  out.push(r.text)
})
if (out.length) process.stdout.write(out.join('\n') + '\n')
