import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function num(v, field, least) {
  if (!INT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  let started = false
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim()
    if (t === '' || t.startsWith('#')) continue
    const f = t.split(/\s+/)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (f.length !== n) throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
