import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'replay' && mode !== 'summary') fail('error: usage: cli.js replay|summary')

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const policies = new Map()
const routes = new Map()
const out = []
const stats = new Map()
let seenEvent = false
let lastTick = null
let totalA = 0
let totalD = 0

class Err extends Error {}
const bad = (m) => { throw new Err(m) }
const num = (s, field, least) => {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) bad(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function advance(p, st, tick) {
  if (p.type === 'bucket') {
    if (st.tokens === undefined) { st.tokens = p.capacity * p.per; st.last = tick; return }
    const dt = tick - st.last
    st.last = tick
    st.tokens += p.refill * dt
    const cap = p.capacity * p.per
    if (st.tokens > cap) st.tokens = cap
  } else {
    if (!st.ticks) st.ticks = []
    const lim = tick - p.span
    st.ticks = st.ticks.filter((t) => t > lim)
  }
}
const allows = (p, st) => (p.type === 'bucket' ? st.tokens >= p.per : BigInt(st.ticks.length) < p.limit)
function record(p, st, tick) {
  if (p.type === 'bucket') st.tokens -= p.per
  else st.ticks.push(tick)
}

try {
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (f.length !== n) {
          bad(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (seenEvent) bad('declarations must come before the first event')
        if (!NAME.test(f[1])) bad(`invalid policy name ${f[1]}`)
        let p
        if (d === 'bucket') {
          p = { type: 'bucket', name: f[1], capacity: num(f[2], 'capacity', 1), refill: num(f[3], 'refill', 0), per: num(f[4], 'per', 1) }
        } else {
          p = { type: 'window', name: f[1], limit: num(f[2], 'limit', 0), span: num(f[3], 'span', 1) }
        }
        if (policies.has(p.name)) bad(`policy ${p.name} is declared twice`)
        p.states = new Map()
        policies.set(p.name, p)
      } else if (d === 'route') {
        if (f.length < 3) bad('expected route <prefix> <policy>...')
        if (seenEvent) bad('declarations must come before the first event')
        if (!NAME.test(f[1])) bad(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) bad(`prefix ${f[1]} is routed twice`)
        const list = []
        for (const nm of f.slice(2)) {
          if (!policies.has(nm)) bad(`unknown policy ${nm}`)
          list.push(policies.get(nm))
        }
        routes.set(f[1], list)
      } else if (d === 'event') {
        if (f.length !== 3) bad('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) bad(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) bad(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        seenEvent = true
        const key = f[2]
        let best = null
        for (const [pre, list] of routes) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let denier = null
        if (best !== null) {
          const list = routes.get(best)
          const sts = list.map((p) => {
            let st = p.states.get(key)
            if (!st) { st = {}; p.states.set(key, st) }
            return st
          })
          list.forEach((p, j) => advance(p, sts[j], tick))
          for (let j = 0; j < list.length; j++) {
            if (!allows(list[j], sts[j])) { denier = list[j]; break }
          }
          if (!denier) list.forEach((p, j) => record(p, sts[j], tick))
        }
        let s = stats.get(key)
        if (!s) { s = { a: 0, d: 0 }; stats.set(key, s) }
        if (denier) { s.d++; totalD++; out.push(`${tick} ${key} deny ${denier.name}`) }
        else { s.a++; totalA++; out.push(`${tick} ${key} allow`) }
      } else {
        bad(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Err) throw new Err(`error: line ${i + 1}: ${e.message}`)
      throw e
    }
  }
} catch (e) {
  if (e instanceof Err) fail(e.message)
  throw e
}

if (mode === 'summary') {
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  for (const k of keys) out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  out.length = 0 + keys.length
  out.push(`total allowed=${totalA} denied=${totalD}`)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
