        if (f.length !== 3) bad('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) bad(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) bad(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        seenEvent = true
        const key = f[2]
        let best = null
        for (const [pre, list] of routes) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let denier = null
        if (best !== null) {
          const list = routes.get(best)
          const sts = list.map((p) => {
            let st = p.states.get(key)
            if (!st) { st = {}; p.states.set(key, st) }
            return st
          })
          list.forEach((p, j) => advance(p, sts[j], tick))
          for (let j = 0; j < list.length; j++) {
            if (!allows(list[j], sts[j])) { denier = list[j]; break }
          }
          if (!denier) list.forEach((p, j) => record(p, sts[j], tick))
        }
        let s = stats.get(key)
        if (!s) { s = { a: 0, d: 0 }; stats.set(key, s) }
        if (denier) { s.d++; totalD++; out.push(`${tick} ${key} deny ${denier.name}`) }
        else { s.a++; totalA++; out.push(`${tick} ${key} allow`) }
      } else {
        bad(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Err) throw new Err(`error: line ${i + 1}: ${e.message}`)
      throw e
    }
  }
} catch (e) {
  if (e instanceof Err) fail(e.message)
  throw e
}

if (mode === 'summary') {
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  for (const k of keys) out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  out.length = 0 + keys.length
  out.push(`total allowed=${totalA} denied=${totalD}`)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
