export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    if (e < 0) { r.authority = s.slice(2); s = '' } else { r.authority = s.slice(2, 2 + e); s = s.slice(2 + e) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const from = a.lastIndexOf(']') + 1
  const c = a.indexOf(':', from)
  let host = a, port = null
  if (c >= 0) { host = a.slice(0, c); port = a.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
export class PctError extends Error {}

function pct(s, name) {
  if (s === null) return null
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new PctError(name)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (t, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function check(s, name) {
  if (s !== null && /%(?![0-9A-Fa-f]{2})/.test(s)) throw new PctError(name)
